<?php require_once 'config/db.php'; require_once 'includes/auth.php'; require_login(); $r=$_SESSION['user']['role']; if($_SERVER['REQUEST_METHOD']==='POST'&&$r==='admin'&&isset($_POST['name'])){ $name=trim($_POST['name']);$desc=trim($_POST['description']??'');$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];$tax=(float)$_POST['tax_rate'];$s=$conn->prepare('INSERT INTO products(name,description,price,stock,tax_rate) VALUES(?,?,?,?,?)');$s->bind_param('ssdid',$name,$desc,$price,$stock,$tax);$s->execute();header('Location:products.php?msg=Product+added');exit;} $rows=$conn->query('SELECT * FROM products ORDER BY name'); include 'includes/header.php'; ?><div class="card"><h2>Products & Inventory</h2><?php if($r==='admin'):?><form method="post" class="grid"><div><label>Name</label><input name="name" required></div><div><label>Price</label><input name="price" type="number" step="0.01" min="0" required></div><div><label>Stock</label><input name="stock" type="number" min="0" required></div><div><label>Tax %</label><input name="tax_rate" type="number" step="0.01" value="18"></div><div><label>Description</label><input name="description"></div><div><button class="btn">Add Product</button></div></form><?php endif;?></div><div class="card"><table><tr><th>Product</th><th>Description</th><th>Price</th><th>Stock</th><th>Tax</th><?php if($r==='customer'):?><th>Add to cart</th><?php endif;?></tr><?php while($p=$rows->fetch_assoc()):?><tr><td><?=h($p['name'])?></td><td><?=h($p['description'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><?=$p['tax_rate']?>%</td><?php if($r==='customer'):?><td><form method="post" action="cart.php"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1" style="width:75px"><button class="btn">Add</button></form></td><?php endif;?></tr><?php endwhile;?></table></div><?php include 'includes/footer.php'; ?>